const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;font:13px/1.35 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;color:var(--ink)}\n.card *{box-sizing:border-box}\n.card button,.card input{font:inherit;color:inherit;margin:0}\n.card button{cursor:pointer;-webkit-tap-highlight-color:transparent}\n.card button:focus-visible,.card input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.lay{width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:10px;background:var(--paper);border-radius:18px;overflow:hidden}\n\n.nav{display:flex;align-items:center;justify-content:space-between;gap:4px;flex:none;min-width:0}\n.ib{width:26px;height:26px;flex:none;border:0;border-radius:50%;background:var(--soft);color:var(--ink);font-size:15px;line-height:1;display:grid;place-items:center;padding:0}\n.ib:disabled{opacity:.3;cursor:default}\n.mlabel{flex:1;min-width:0;border:0;background:none;font-weight:700;font-size:14px;color:var(--ink);padding:3px 4px;white-space:nowrap}\n.caret{font-size:9px;color:var(--muted);margin-left:3px}\n\n.sum{display:flex;flex-direction:column;gap:4px;min-width:0}\n.sum .k{color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sum .big{font-size:28px;font-weight:800;letter-spacing:-.02em;line-height:1.1;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.bar{height:8px;border-radius:99px;background:var(--soft);overflow:hidden;flex:none}\n.bar i{display:block;height:100%;border-radius:99px;background:var(--accent)}\n.sum.over .big{color:#B4533A}\n.sum.over .bar i{background:#B4533A}\n.meta{display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:12px;color:var(--muted);min-width:0}\n.meta .sp{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.link{border:0;border-radius:99px;background:var(--soft);color:var(--ink);padding:2px 8px;font-size:12px;white-space:nowrap;flex:none}\n.hint{font-size:12px;color:var(--muted)}\n\n.btn{border:0;border-radius:10px;padding:0 12px;min-height:34px;font-weight:700;white-space:nowrap;background:var(--soft);color:var(--ink)}\n.btn.primary{background:var(--accent);color:var(--on-accent)}\n.btn.ghost{background:var(--soft);color:var(--ink)}\n.btn.danger{background:#B4533A;color:#FFFFFF}\n.btn:disabled{opacity:.5;cursor:default}\n\n.tabs{display:flex;gap:2px;background:var(--soft);border-radius:10px;padding:2px;flex:1;min-width:0}\n.tab{flex:1;min-width:0;border:0;border-radius:8px;background:none;padding:5px 2px;font-size:12px;color:var(--muted);white-space:nowrap}\n.tab.on{background:var(--panel-paper);color:var(--ink);font-weight:700;box-shadow:0 0 0 1px var(--line)}\n\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain}\n.rows,.cats{display:flex;flex-direction:column;min-width:0}\n.row{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;border:0;border-bottom:1px solid var(--line);background:none;padding:7px 2px;text-align:left;min-width:0;color:var(--ink)}\n.row.sel{background:var(--soft);border-radius:8px}\n.rl{display:flex;flex-direction:column;min-width:0;flex:1}\n.rc{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rs{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.ra{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap;flex:none}\n.ra.neg{color:#B4533A}\n.crow{padding:6px 2px;border-bottom:1px solid var(--line);min-width:0}\n.ctop{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:4px;min-width:0}\n.cn{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n.ca{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap;flex:none}\n.ca em{font-style:normal;font-weight:400;font-size:11px;color:var(--muted)}\n.cbar{height:6px;border-radius:99px;background:var(--soft);overflow:hidden}\n.cbar i{display:block;height:100%;border-radius:99px;background:var(--accent-alt)}\n.empty{color:var(--muted);text-align:center;padding:16px 6px;font-size:12px}\n\n/* 3x3 */\n.lay.s .main{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;justify-content:center}\n.bot{display:flex;gap:6px;align-items:center;flex:none}\n.bot .btn{padding:0 9px;min-height:32px;font-size:12px}\n.bot .tabs{flex:1}\n\n/* 6x3 */\n.lay.w{flex-direction:row;gap:12px}\n.lcol{flex:0 0 42%;min-width:0;display:flex;flex-direction:column;justify-content:space-between;gap:6px}\n.rcol{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding-left:12px;border-left:1px solid var(--line)}\n\n/* 3x6 */\n.lay.t .sum,.lay.l .sum{background:var(--panel-paper);border-radius:14px;padding:10px;gap:6px}\n.lay.t .big{font-size:32px}\n\n/* 6x6 */\n.lay.l{gap:8px;padding:12px}\n.lay.l .top{display:flex;align-items:center;gap:10px;flex:none}\n.lay.l .top .nav{flex:1;max-width:220px}\n.lay.l .big{font-size:40px}\n.cols{flex:1;min-height:0;display:flex;gap:14px}\n.pane{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:4px}\n.pane+.pane{padding-left:14px;border-left:1px solid var(--line)}\n.pane h3{margin:0;font-size:12px;font-weight:600;color:var(--muted);flex:none}\n\n/* panels: form, budget, months */\n.phead{display:flex;align-items:center;justify-content:space-between;gap:8px;flex:none}\n.phead h2{margin:0;font-size:15px;font-weight:700}\n.pbody{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px;overscroll-behavior:contain}\n.pfoot{display:flex;align-items:center;gap:6px;flex:none}\n.pfoot .btn{flex:1;min-height:34px}\n.pfoot .ask{flex:1.2;font-size:12px;color:var(--muted)}\n.f{display:grid;grid-template-columns:34px minmax(0,1fr);align-items:center;gap:6px;min-width:0}\n.f.top{align-items:start}\n.f>span{color:var(--muted);font-size:12px}\n.inp{width:100%;min-width:0;height:32px;border:1px solid var(--line);border-radius:9px;background:var(--panel-paper);color:var(--ink);padding:0 8px}\n.inp:focus{border-color:var(--accent)}\n.amtw{position:relative;min-width:0}\n.yen{position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--muted);font-weight:700;pointer-events:none}\n.inp.amt{height:38px;font-size:18px;font-weight:700;padding-left:24px;font-variant-numeric:tabular-nums}\n.catw{display:flex;flex-direction:column;gap:6px;min-width:0}\n.chips{display:flex;flex-wrap:wrap;gap:5px}\n.chip{border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);border-radius:99px;padding:4px 10px;font-size:12px;white-space:nowrap}\n.chip.plus{border-style:dashed}\n.chip.on{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.err{font-size:12px;font-weight:600;color:var(--ink);background:var(--soft);border-left:3px solid #B4533A;border-radius:6px;padding:5px 8px}\n.note{margin:0;font-size:12px;color:var(--muted)}\n\n.card[data-size=\"6x3\"] .pbody.form,.card[data-size=\"6x6\"] .pbody.form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);grid-auto-rows:min-content;align-content:start;gap:8px 16px}\n.card[data-size=\"6x3\"] .pbody.form .f.cat,.card[data-size=\"6x6\"] .pbody.form .f.cat{grid-column:2;grid-row:1 / span 3;grid-template-columns:minmax(0,1fr);gap:4px}\n.card[data-size=\"6x3\"] .pbody.form .err,.card[data-size=\"6x6\"] .pbody.form .err{grid-column:1 / -1}\n.card[data-size=\"6x3\"] .pfoot,.card[data-size=\"6x6\"] .pfoot{justify-content:flex-end}\n.card[data-size=\"6x3\"] .pfoot .btn,.card[data-size=\"6x6\"] .pfoot .btn{flex:0 0 110px}\n.card[data-size=\"6x3\"] .pfoot .ask,.card[data-size=\"6x6\"] .pfoot .ask{flex:1;text-align:right}\n.card[data-size=\"6x6\"] .pnl{gap:10px}\n.card[data-size=\"6x6\"] .pbody{gap:12px}\n";
const BK_CATS=['餐饮','交通','居家','购物','娱乐','医疗','其他'];
const BK_MAX=100000000;

function initialize(s){
  const n=Object.assign({},s||{});
  let ch=!s;
  const b=n.budget;
  if(!b||typeof b!=='object'||typeof b.base!=='number'||!(b.base>0)){
    n.budget={base:3000,changes:(b&&b.changes&&typeof b.changes==='object')?b.changes:{}};
    ch=true;
  }
  if(!Array.isArray(n.expenses)){n.expenses=[];ch=true;}
  if(!Array.isArray(n.categories)){n.categories=BK_CATS.slice();ch=true;}
  return ch?n:s;
}

function bkNorm(s){
  s=s||{};
  const b=s.budget||{};
  return {
    base:(typeof b.base==='number'&&b.base>0)?b.base:3000,
    changes:(b.changes&&typeof b.changes==='object')?b.changes:{},
    cats:Array.isArray(s.categories)?s.categories:BK_CATS.slice(),
    list:Array.isArray(s.expenses)?s.expenses.filter(e=>e&&typeof e.date==='string'&&typeof e.amount==='number'):[]
  };
}

function bkBudgetFor(N,month){
  let v=N.base,best='';
  Object.keys(N.changes).forEach(k=>{
    if(k<=month&&k>best&&typeof N.changes[k]==='number'&&N.changes[k]>0){best=k;v=N.changes[k];}
  });
  return v;
}

function bkCents(n){return Math.round(n*100);}

function bkFmt(c){
  const neg=c<0;
  const a=Math.abs(Math.round(c));
  const yuan=Math.floor(a/100),fen=a%100;
  let t=String(yuan).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  if(fen)t+='.'+(fen<10?'0':'')+fen;
  return (neg?'-':'')+t;
}

function bkPad(n){return n<10?'0'+n:String(n);}

function bkShift(m,d){
  let y=Number(m.slice(0,4)),mo=Number(m.slice(5,7))-1+d;
  y+=Math.floor(mo/12);
  mo=((mo%12)+12)%12;
  return y+'-'+bkPad(mo+1);
}

function bkDim(m){return new Date(Number(m.slice(0,4)),Number(m.slice(5,7)),0).getDate();}

function bkLabel(m){return m.slice(0,4)+'年'+Number(m.slice(5,7))+'月';}

function bkValidDate(s){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;
  const y=Number(s.slice(0,4)),m=Number(s.slice(5,7)),d=Number(s.slice(8,10));
  const t=new Date(y,m-1,d);
  return y>=1970&&t.getFullYear()===y&&t.getMonth()===m-1&&t.getDate()===d;
}

function bkParse(v){
  const t=String(v==null?'':v).replace(/[,\s，]/g,'').replace(/[。．]/g,'.').replace(/^[¥￥]/,'');
  if(!/^\d+(\.\d{1,2})?$/.test(t))return null;
  const n=Number(t);
  return (n>0&&n<BK_MAX)?n:null;
}

function bkCmp(a,b){
  if(a.date!==b.date)return a.date<b.date?1:-1;
  const x=a.at||0,y=b.at||0;
  if(x!==y)return y-x;
  return 0;
}

function bkCalc(N,month){
  const rows=N.list.filter(e=>e.date.slice(0,7)===month).sort(bkCmp);
  let spent=0;
  const by=new Map();
  rows.forEach(e=>{
    const c=bkCents(e.amount);
    const k=e.cat||'其他';
    spent+=c;
    by.set(k,(by.get(k)||0)+c);
  });
  const cats=[];
  by.forEach((c,k)=>{cats.push({name:k,c:c});});
  cats.sort((a,b)=>b.c-a.c);
  const bc=bkCents(bkBudgetFor(N,month));
  return {rows:rows,spent:spent,cats:cats,budget:bc,left:bc-spent};
}

function bkMonths(N,cur,month){
  const set={};
  set[cur]=1;
  set[month]=1;
  N.list.forEach(e=>{set[e.date.slice(0,7)]=1;});
  return Object.keys(set).sort();
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,size}=ctx;
  const N=bkNorm(state);
  const cur=day().slice(0,7);
  if(!ui.month)ui.month=cur;
  if(!ui.view)ui.view='main';
  if(!ui.tab)ui.tab='sum';
  const month=ui.month;
  const D=bkCalc(N,month);
  const isS=size==='3x3',isW=size==='6x3',isT=size==='3x6',isL=size==='6x6';
  const curTab=isS?ui.tab:(ui.tab==='list'?'list':'cat');
  const mset=bkMonths(N,cur,month);
  const minM=mset[0],maxM=mset[mset.length-1];
  let toFocus=null;

  function go(p){Object.assign(ui,p);redraw();}
  function setErr(m){ui.err=m;redraw();}
  function back(){go({view:'main',draft:null,bDraft:null,err:'',confirmDel:false,saving:false});}
  function nextUi(p){return Object.assign({},ui,{view:'main',draft:null,bDraft:null,err:'',confirmDel:false,saving:false},p||{});}
  function fail(e){ui.saving=false;ui.err='保存失败：'+((e&&e.message)||'请重试');redraw();}

  function openAdd(){
    let lastCat=N.cats[0]||'餐饮',t=-1;
    N.list.forEach(e=>{if((e.at||0)>t){t=e.at||0;lastCat=e.cat||lastCat;}});
    go({view:'form',err:'',confirmDel:false,saving:false,draft:{id:null,amount:'',cat:lastCat,date:month===cur?day():month+'-01',note:'',adding:false,newCat:''}});
  }
  function openEdit(e){
    go({view:'form',err:'',confirmDel:false,saving:false,draft:{id:e.id,amount:String(e.amount),cat:e.cat||'其他',date:e.date,note:e.note||'',adding:false,newCat:''}});
  }
  function openBudget(){go({view:'budget',err:'',saving:false,bDraft:String(D.budget/100)});}

  function saveEntry(){
    const d=ui.draft;
    if(!d||ui.saving)return;
    const amt=bkParse(d.amount);
    const cat=String((d.adding?d.newCat:d.cat)||'').trim();
    if(amt==null){setErr('金额要大于 0，最多两位小数');return;}
    if(!cat){setErr('请选择或输入类别');return;}
    if(!bkValidDate(d.date)){setErr('请填写有效日期');return;}
    const note=String(d.note||'').trim().slice(0,40);
    const isNew=!d.id;
    const id=d.id||uid();
    const date=d.date;
    ui.saving=true;ui.err='';redraw();
    commit(s=>{
      const n=bkNorm(s);
      let list;
      if(isNew){
        list=n.list.concat([{id:id,amount:amt,cat:cat,date:date,note:note,at:Date.now()}]);
      }else{
        if(!n.list.some(e=>e.id===id))throw new Error('这笔记录已不存在');
        list=n.list.map(e=>e.id===id?Object.assign({},e,{amount:amt,cat:cat,date:date,note:note}):e);
      }
      const cats=n.cats.indexOf(cat)<0?n.cats.concat([cat]):n.cats;
      return Object.assign({},s,{expenses:list,categories:cats});
    },nextUi({month:date.slice(0,7)})).catch(fail);
  }

  function delEntry(){
    const d=ui.draft;
    if(!d||!d.id||ui.saving)return;
    const id=d.id;
    ui.saving=true;redraw();
    commit(s=>{
      const n=bkNorm(s);
      return Object.assign({},s,{expenses:n.list.filter(e=>e.id!==id)});
    },nextUi()).catch(fail);
  }

  function saveBudget(){
    if(ui.saving)return;
    const v=bkParse(ui.bDraft);
    if(v==null){setErr('预算要大于 0，最多两位小数');return;}
    const m=month;
    ui.saving=true;ui.err='';redraw();
    commit(s=>{
      const n=bkNorm(s);
      const ch=Object.assign({},n.changes);
      ch[m]=v;
      return Object.assign({},s,{budget:{base:n.base,changes:ch}});
    },nextUi()).catch(fail);
  }

  function empty(msg){return el('div',{class:'empty'},msg);}
  function scroll(child){return el('div',{class:'scroll'},child);}
  function addBtn(){return el('button',{class:'btn primary',type:'button',onclick:openAdd},'＋ 记一笔');}

  function nav(){
    return el('div',{class:'nav'},
      el('button',{class:'ib',type:'button','aria-label':'上一个月',disabled:month<=minM,onclick:()=>go({month:bkShift(month,-1)})},'‹'),
      el('button',{class:'mlabel',type:'button','aria-label':'查看历史月份',onclick:()=>go({view:'months'})},bkLabel(month),el('span',{class:'caret'},'▾')),
      el('button',{class:'ib',type:'button','aria-label':'下一个月',disabled:month>=maxM,onclick:()=>go({month:bkShift(month,1)})},'›')
    );
  }

  function summary(){
    const over=D.left<0;
    const pctRaw=D.budget>0?D.spent/D.budget*100:0;
    const w=Math.max(0,Math.min(100,pctRaw));
    const who=month===cur?'本月':'该月';
    const kids=[
      el('div',{class:'k'},over?'⚠ '+who+'已超支':who+'还剩'),
      el('div',{class:'big'},'¥'+bkFmt(Math.abs(D.left))),
      el('div',{class:'bar',role:'progressbar','aria-label':'预算已用','aria-valuemin':'0','aria-valuemax':'100','aria-valuenow':String(Math.round(w))},el('i',{style:'width:'+w+'%'})),
      el('div',{class:'meta'},
        el('span',{class:'sp'},'已花 ¥'+bkFmt(D.spent)+(isS?'':' · '+Math.round(pctRaw)+'%')),
        el('button',{class:'link',type:'button','aria-label':'修改月预算',onclick:openBudget},'预算 ¥'+bkFmt(D.budget)+' ✎')
      )
    ];
    if((isT||isL)&&month===cur&&D.left>0){
      const days=bkDim(month)-Number(day().slice(8,10))+1;
      if(days>0)kids.push(el('div',{class:'hint'},'还剩 '+days+' 天，日均可花 ¥'+bkFmt(Math.floor(D.left/days))));
    }
    return el('div',{class:'sum'+(over?' over':'')},...kids);
  }

  function catBlock(){
    if(!D.cats.length)return empty('本月还没有支出');
    return el('div',{class:'cats'},...D.cats.map(c=>{
      const share=D.spent>0?c.c/D.spent*100:0;
      return el('div',{class:'crow'},
        el('div',{class:'ctop'},
          el('span',{class:'cn'},c.name),
          el('span',{class:'ca'},'¥'+bkFmt(c.c),el('em',{},' '+Math.round(share)+'%'))
        ),
        el('div',{class:'cbar'},el('i',{style:'width:'+share+'%'}))
      );
    }));
  }

  function listBlock(){
    if(!D.rows.length)return empty('还没有记账，点「记一笔」开始');
    return el('div',{class:'rows'},...D.rows.map(e=>
      el('button',{class:'row',type:'button','aria-label':'修改 '+e.date+' '+e.cat+' '+bkFmt(bkCents(e.amount))+' 元',onclick:()=>openEdit(e)},
        el('span',{class:'rl'},
          el('span',{class:'rc'},e.cat||'其他'),
          el('span',{class:'rs'},e.date.slice(5)+(e.note?' · '+e.note:''))
        ),
        el('span',{class:'ra'},'¥'+bkFmt(bkCents(e.amount)))
      )
    ));
  }

  function tabs(items){
    return el('div',{class:'tabs',role:'tablist'},...items.map(t=>
      el('button',{class:'tab'+(curTab===t[0]?' on':''),type:'button',role:'tab','aria-selected':String(curTab===t[0]),onclick:()=>go({tab:t[0]})},t[1])
    ));
  }


  function shell(title,body,foot,onBack,cls){
    const kids=[
      el('div',{class:'phead'},el('h2',{},title),el('button',{class:'ib',type:'button','aria-label':'关闭',onclick:onBack},'✕')),
      el('div',{class:'pbody '+(cls||'')},...body)
    ];
    if(foot)kids.push(el('div',{class:'pfoot'},...foot));
    return el('div',{class:'lay pnl'},...kids);
  }

  function errNode(){
    return ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
  }

  function amountField(label,value,onInput,onEnter){
    const inp=el('input',{class:'inp amt',type:'text',inputmode:'decimal',placeholder:'0.00',value:value,maxlength:'12','aria-label':label+'（元）',
      oninput:e=>{onInput(e.target.value);},
      onkeydown:e=>{if(e.key==='Enter')onEnter();}});
    return el('label',{class:'f'},el('span',{},label),el('div',{class:'amtw'},el('b',{class:'yen'},'¥'),inp));
  }

  function formView(){
    const d=ui.draft;
    const edit=!!d.id;
